import React, { useEffect, useState } from 'react';
import { Github, Linkedin, Twitter, Instagram } from 'lucide-react';

export default function HeroSection() {
  const [scrollY, setScrollY] = useState(0);

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <section className="relative min-h-screen overflow-hidden pt-20">
      {/* Spline 3D Background */}
      <div className="absolute inset-0 w-full h-full">
        <iframe
          src="https://my.spline.design/cubes-A0T7CP5J2qsawolli9BlhInB/"
          className="w-full h-full border-0"
          title="3D Cubes Scene"
        />

        {/* Dark Majestic Overlay */}
        <div className="absolute inset-0 pointer-events-none">
          <div
            className="absolute inset-0"
            style={{
              background: `
                linear-gradient(
                  180deg,
                  rgba(0, 0, 0, 0.3) 0%,
                  rgba(0, 0, 0, 0.5) 25%,
                  rgba(0, 0, 0, 0.7) 50%,
                  rgba(0, 0, 0, 0.85) 75%,
                  rgba(0, 0, 0, 0.95) 100%
                )
              `,
            }}
          />

          {/* Subtle teal accent overlay */}
          <div
            className="absolute inset-0"
            style={{
              background: `
                radial-gradient(
                  ellipse at center bottom,
                  rgba(6, 182, 212, 0.08) 0%, /* Teal primary from palette */
                  rgba(6, 182, 212, 0.04) 40%,
                  transparent 70%
                )
              `,
            }}
          />
        </div>
      </div>

      {/* Minimal Parallax Elements */}
      <div
        className="absolute inset-0 opacity-20 pointer-events-none"
        style={{
          transform: `translateY(${scrollY * 0.5}px)`,
        }}
      >
        <div className="absolute top-20 left-10 w-1 h-1 bg-teal-500 rounded-full"></div>
        <div className="absolute top-40 right-20 w-0.5 h-0.5 bg-white rounded-full"></div>
        <div className="absolute bottom-40 left-20 w-1 h-1 bg-teal-300 rounded-full"></div>
      </div>

      {/* Content */}
      <div className="relative z-10 container mx-auto px-6 lg:px-16 flex items-center justify-between max-w-7xl h-screen">
        {/* Left Content */}
        <div
          className="flex-1 max-w-2xl"
          style={{
            transform: `translateY(${scrollY * 0.2}px)`,
          }}
        >
          <div className="mb-6">
            <p className="text-gray-400 text-sm font-medium mb-2 tracking-widest uppercase">Hello, My name is</p>
            <h1 className="text-6xl lg:text-8xl font-black leading-tight tracking-tight">
              <span className="text-white">Badr Eddine</span>
              <br />
              <span className="text-white relative">
                Diyaf
                <div className="absolute -bottom-2 left-0 w-16 h-0.5 bg-teal-500"></div>
              </span>
            </h1>
          </div>
        </div>

        {/* Right Content - Image and Social */}
        <div
          className="flex-1 flex justify-end items-center relative"
          style={{
            transform: `translateY(${scrollY * -0.1}px)`,
          }}
        >
          <div className="relative">
            {/* Profile Image */}
            <div className="relative w-80 h-96 rounded-3xl overflow-hidden bg-black/80 backdrop-blur-sm border border-gray-800">
              <img
                src="/placeholder.svg?height=400&width=320"
                alt="Badr Eddine Diyaf"
                className="w-full h-full object-cover grayscale"
              />

              {/* Dark Gradient Overlay */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20 to-transparent"></div>

              {/* Subtle teal accent line */}
              <div className="absolute bottom-0 left-0 right-0 h-0.5 bg-gradient-to-r from-transparent via-teal-500 to-transparent"></div>
            </div>

            {/* Social Media Buttons */}
            <div
              className="absolute -right-6 top-1/2 transform -translate-y-1/2 flex flex-col gap-4"
              style={{
                transform: `translateY(${scrollY * 0.1}px)`,
              }}
            >
              <a
                href="https://github.com"
                className="w-12 h-12 bg-black/90 backdrop-blur-sm border border-gray-800 hover:border-teal-500 hover:bg-gray-900 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 group"
              >
                <Github className="w-5 h-5 text-gray-400 group-hover:text-white" />
              </a>
              <a
                href="https://linkedin.com"
                className="w-12 h-12 bg-black/90 backdrop-blur-sm border border-gray-800 hover:border-teal-500 hover:bg-gray-900 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 group"
              >
                <Linkedin className="w-5 h-5 text-gray-400 group-hover:text-white" />
              </a>
              <a
                href="https://x.com"
                className="w-12 h-12 bg-black/90 backdrop-blur-sm border border-gray-800 hover:border-teal-500 hover:bg-gray-900 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 group"
              >
                <Twitter className="w-5 h-5 text-gray-400 group-hover:text-white" />
              </a>
              <a
                href="https://instagram.com"
                className="w-12 h-12 bg-black/90 backdrop-blur-sm border border-gray-800 hover:border-teal-500 hover:bg-gray-900 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 group"
              >
                <Instagram className="w-5 h-5 text-gray-400 group-hover:text-white" />
              </a>
            </div>
          </div>
        </div>
      </div>

      {/* Scroll Indicator */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-10">
        <div className="w-6 h-10 border-2 border-gray-600 rounded-full flex justify-center">
          <div className="w-0.5 h-3 bg-teal-500 rounded-full mt-2 animate-bounce"></div>
        </div>
      </div>
    </section>
  );
}
